def paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    determine the number of such groups and return the list of their starting indices.
    >>> paren_groups('( ) (( )) (( )( ))')
    [0, 2, 5]
    """
    start_index: List[int] = []
    group_num = 0
    paren_num = 0
    for i, c in enumerate(paren_string):
        if c == '(':
            paren_num += 1
            if paren_num == 1:
                start_index.append(i)
        else:
            paren_num -= 1
            if paren_num == 0:
                group_num += 1
    return start_index


