    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the maximum depth of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_depth('(()()) ((())) () ((())()())')
    [2, 3, 1, 4]
    """
    stack = []
    depths = []
    max_depth = 0

    for i, par in enumerate(paren_string):
        if par == '(':
            stack.append(i)
            max_depth = max(max_depth, len(stack))
        elif par == ')':
            stack.pop()
    return [max_depth]

