def parse_nested_parens_impl(paren_string: str, index: int = 0, nesting: int = 0) -> int:
    """ Implementation for parse_nested_parens function above.

    >>> parse_nested_parens_impl('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    if not paren_string:
        return nesting
    while paren_string[index] in ('(', ')'):
        if paren_string[index] == '(':
            nesting += 1
        elif paren_string[index] == ')':
            nesting -= 1
        index += 1
    return parse_nested_parens_impl(paren_string, index, nesting)


