def stddev(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Standard Deviation
    for the entire dataset:
    sd = sqrt (average (x - x_mean)^2)
    >>> stddev([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    n = len(numbers)
    avg = sum(numbers) / n
    return mean_absolute_deviation([x - avg for x in numbers])


def z_score(numbers: List[float]) -> List[float]:
    """ For a given list of input numbers, calculate Z Score
    for the entire dataset:
    z = (x - mean) / sd
    >>> z_score([1.0, 2.0, 3.0, 4.0])
    [0.0, 0.0, 0.0, 0.0]
    """
    return [(x - mean(numbers)) / stddev(numbers) for x in numbers]

    return sum((number - mean(numbers)) for number in numbers) / len(numbers)


def mean(numbers: List[float]) -> float:
    """ Returns the arithmetic mean of the data elements in numbers
    >>> mean([-10, 10])
    0.0
    """
    return sum(numbers) / len(numbers)


def mean_absolute_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the Mean Absolute
    Deviation around the mean of this dataset.
    Mean Absolute Deviation is the average absolute difference between
    each element and the mean of this dataset:
    MAD = average | x - mean_of_data | """
    return sum((number - mean(numbers)) for number in numbers) / len(numbers)


