def parse_parens_string(paren_string: str) -> int:
    """ Input to this function is a string representing one group of parentheses
    E.g. '()()'

    >>> parse_parens_string('()()')
    2
    """
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
    return count


def get_parens_depth(paren_string: str) -> int:
    """ Input to this function is a string representing one group of parentheses
    E.g. '()()'

    >>> get_parens_depth('()')
    0
    >>> get_parens_depth('())())()')
    3
    """
    if len(paren_string) == 0:
        return 0
    if len(paren_string) == 1:
        return 1
    return 1 + max(map(get_parens_depth, paren_string.split('()')))


