def count_nesting_for_group(paren_group: str) -> int:
    """
    Recursively count the number of nested pairs of parentheses in a paren_group
    :param paren_group: Input string representing paren_group
    :return: Depth of nesting
    """
    if paren_group == '':
        return 0
    count = 0
    # Start from 1 since we want to exclude the first level as it is always '()', no nesting
